(()=>{
const $=id=>document.getElementById(id),svg=$('plan'),NS='http://www.w3.org/2000/svg';let state={...RanchEngine.defaults},layout,selected='house',drag=null,routes=true,zoom=1;
try{state=RanchEngine.normalize(JSON.parse(localStorage.getItem('abbie-ranch-v2'))||state);}catch(e){}
function el(tag,attrs={},parent=svg){const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);parent.appendChild(n);return n;}
function text(t,x,y,size=3,parent=svg){const n=el('text',{x,y,'font-size':size,'text-anchor':'middle',fill:'#554e46'},parent);n.textContent=t;return n;}
const rect=(a,fill,parent=svg,more={})=>el('rect',{x:a.x,y:a.y,width:a.w,height:a.d,fill,...more},parent);
function draw(){layout=RanchEngine.generate(state);state=layout.state;svg.replaceChildren();svg.setAttribute('viewBox',`-12 -13 ${state.width+24} ${state.depth+32}`);
 const W=state.width,D=state.depth;
 RanchArt.render(svg,layout,routes,id=>{selected=id;inspect();$('inspect-sheet').showModal();});
 for(const [x,y,sx,sy]of [[0,0,-1,-1],[W,0,1,-1],[W,D,1,1],[0,D,-1,1]]){el('circle',{cx:x,cy:y,r:4,fill:'#fff8e8',stroke:'#71587c','stroke-width':1,'pointer-events':'none'});const c=el('circle',{cx:x,cy:y,r:Math.max(4,22/(svg.getScreenCTM()?.a||2)),class:'corner',tabindex:0,role:'button','aria-label':'Resize land corner; use arrow keys'});c.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')state.width-=5;if(e.key==='ArrowRight')state.width+=5;if(e.key==='ArrowUp')state.depth-=5;if(e.key==='ArrowDown')state.depth+=5;draw();save();}};c.onpointerdown=e=>{e.preventDefault();const m=svg.getScreenCTM();drag={x:e.clientX,y:e.clientY,w:W,d:D,sx,sy,scale:m.a};svg.setPointerCapture(e.pointerId);};}
 $('dimensions').textContent=`${layout.acres.toFixed(1)} acres · seed ${state.seed}`;$('seed').value=state.seed;$('width').value=W;$('depth').value=D;$('trees').value=state.trees;$('tree-value').textContent=state.trees+'%';
 document.querySelectorAll('.pillset').forEach(g=>g.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',Array.isArray(state[g.dataset.group])?state[g.dataset.group].includes(b.dataset.value):state[g.dataset.group]===b.dataset.value)));
 $('layout-status').textContent=`${layout.items.length} features · ${layout.paths.length} connected gates · ${layout.trees.length} landscape trees.`+(layout.omitted.length?' Could not fit: '+layout.omitted.join(', ')+'.':'')+(layout.unreachable.length?' No dry route: '+layout.unreachable.join(', ')+'.':' All placed gates connect to the entrance.');inspect();
}
function inspect(){document.querySelectorAll('.land-object').forEach(n=>n.classList.toggle('selected',n.getAttribute('aria-label')===layout.items.find(a=>a.id===selected)?.name));const a=layout.items.find(a=>a.id===selected)||layout.items[0];$('selected-title').textContent=a?a.name:'Open land';$('selected-reason').textContent=a?`${a.reason} Footprint: ${a.w.toFixed(0)} × ${a.d.toFixed(0)} m.`:'Try a larger property.';}
function save(){try{localStorage.setItem('abbie-ranch-v2',JSON.stringify(state));$('save-state').textContent='Saved on this device';}catch(e){$('save-state').textContent='Local saving unavailable';}}
let pending=false;svg.onpointermove=e=>{if(!drag)return;state.width=Math.round(Math.max(90,Math.min(260,drag.w+(e.clientX-drag.x)/drag.scale*drag.sx))/5)*5;state.depth=Math.round(Math.max(90,Math.min(260,drag.d+(e.clientY-drag.y)/drag.scale*drag.sy))/5)*5;if(!pending){pending=true;requestAnimationFrame(()=>{pending=false;draw();});}};svg.onpointerup=()=>{drag=null;save();};svg.onpointercancel=()=>{drag=null;save();};
document.querySelectorAll('.pillset button').forEach(b=>b.onclick=()=>{const key=b.parentElement.dataset.group,v=b.dataset.value;if(Array.isArray(state[key]))state[key]=state[key].includes(v)?state[key].filter(x=>x!==v):[...state[key],v];else state[key]=v;draw();save();});
for(const id of ['width','depth','trees'])$(id).onchange=$(id).onblur=()=>{state[id]=+$(id).value;draw();save();$('generation-feedback').textContent='Ranch updated · '+layout.items.length+' features. Tap Inspect for layout details.';};$('routes').onchange=()=>{routes=$('routes').checked;draw();};$('variation').onclick=()=>{state.seed=freshSeed();grow('A fresh landscape is ready');};
$('prompt-form').onsubmit=e=>{e.preventDefault();const t=$('prompt').value.toLowerCase();if(!/ranch|farm|homestead/.test(t)){$('prompt-note').textContent='This grammar understands ranches, farms and homesteads. Try “horse ranch with a pond”.';return;}state={...RanchEngine.defaults,seed:freshSeed(),needs:[],extras:[]};if(/horse/.test(t))state.kind='horses';if(/cattle|cow/.test(t))state.kind='cattle';if(/small|tiny/.test(t)){state.width=100;state.depth=100;}if(/large|spacious/.test(t)){state.width=240;state.depth=220;}if(/creek|stream/.test(t))state.terrain='creek';else if(/meadow|dry|no water/.test(t))state.terrain='meadow';if(/summer/.test(t))state.motif='summer';if(/halloween|spooky/.test(t))state.motif='halloween';for(const [word,v]of [['garden','garden'],['orchard','orchard'],['guest','guest'],['chicken','chickens']])if(t.includes(word))state.needs.push(v);if(/whims|magic/.test(t))state.extras.push('whimsy');if(/party|festival/.test(t))state.extras.push('party');$('prompt-note').textContent='Grown from recognized keywords. Use Shape to refine the details.';$('prompt').blur();$('brief-sheet').close();grow('Your new ranch is ready');};
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==b.dataset.page);document.querySelectorAll('nav button').forEach(n=>n.classList.toggle('active',n.dataset.page===b.dataset.page));});
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({...layout,format:'abbies-world-ranch-blueprint',units:'metres',simulation:'conceptual layout; animals are illustrative'},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='abbies-ranch-'+state.seed+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function freshSeed(){return state.seed>=2147483646?1:state.seed+1;}
function grow(message){draw();save();svg.classList.remove('growing');requestAnimationFrame(()=>svg.classList.add('growing'));$('generation-feedback').textContent=`${message} · seed ${state.seed}. ${layout.items.length} features`+(layout.omitted.length?' · Some features could not fit. Tap Inspect.':layout.unreachable.length?' · Some gates have no dry route. Tap Inspect.':' · All gates connected.');}
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>$(b.dataset.open).showModal());
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientY<r.top||e.clientX<r.left||e.clientX>r.right)d.close();}}));
$('inspect-open').onclick=()=>$('inspect-sheet').showModal();
$('replay').onclick=()=>{state.seed=Math.max(1,Math.min(2147483646,Math.round(+$('seed').value||1)));$('design-sheet').close();grow('Landscape replayed');};
function setZoom(z){zoom=Math.max(1,Math.min(3,z));svg.style.width=(zoom*100)+'%';svg.style.height=(zoom*100)+'%';$('zoom-out').disabled=zoom===1;$('zoom-in').disabled=zoom===3;}
$('zoom-in').onclick=()=>setZoom(zoom+.5);$('zoom-out').onclick=()=>setZoom(zoom-.5);$('zoom-fit').onclick=()=>{setZoom(1);document.querySelector('.plan-wrap').scrollTo(0,0);};
if(window.visualViewport){const syncViewport=()=>{document.documentElement.style.setProperty('--visible-height',window.visualViewport.height+'px');document.documentElement.style.setProperty('--keyboard-offset',Math.max(0,window.innerHeight-window.visualViewport.height-window.visualViewport.offsetTop)+'px');};window.visualViewport.addEventListener('resize',syncViewport);syncViewport();}
draw();setZoom(1);
})();
